nvfp4._use_qwen38_qpn_batch_fused_w13:
def _use_qwen38_qpn_batch_fused_w13(
    layer: RoutedExperts,
    x: torch.Tensor,
    topk_ids: torch.Tensor,
) -> bool:
    """Admit the retained split-preserving W13+SwiGLU fusion widths."""
    return bool(
        envs.VLLM_SM70_NVFP4_QWEN38_MOE_QPN_BATCH_FUSED_W13
        and x.shape[0] in _QWEN38_QPN_BATCH_FUSED_W13_TOKENS
        and layer.swiglu_limit is None
        and sm70_ops.has_nvfp4_qpn_w13_swiglu_batch_dispatch()
        and _use_qwen38_qpn_batch_decode(layer, x, topk_ids)
    )

nvfp4._grouped_decode_context_ok:
def _grouped_decode_context_ok() -> bool:
    """Use CPU metadata, never GPU readback, to exclude prefill and verify."""
    if not is_forward_context_available():
        return False
    context = get_forward_context()
    metadata = context.attn_metadata
    # DBO/list metadata needs per-microbatch ownership, not a shared decision.
    if not isinstance(metadata, dict) or not metadata:
        return False
    key = "sm70_grouped_moe_decode"
    if key not in context.additional_kwargs:
        seen_decode = False
        allowed = True
        for meta in metadata.values():
            prefills = getattr(meta, "num_prefills", 0)
            prefill_tokens = getattr(meta, "num_prefill_tokens", 0)
            if (
                not isinstance(prefills, int)
                or not isinstance(prefill_tokens, int)
                or prefills != 0
                or prefill_tokens != 0
            ):
                allowed = False
                break
            max_query = getattr(meta, "max_query_len", None)
            if max_query is not None:
                if not isinstance(max_query, int) or max_query != 1:
                    allowed = False
                    break
                seen_decode = True
            num_decodes = getattr(meta, "num_decodes", None)
            if num_decodes is not None:
                decode_tokens = getattr(meta, "num_decode_tokens", None)
                if (
                    not isinstance(num_decodes, int)
                    or not isinstance(decode_tokens, int)
                    or decode_tokens != num_decodes
                ):
                    allowed = False
                    break
                seen_decode |= num_decodes > 0
        context.additional_kwargs[key] = bool(allowed and seen_decode)
    return bool(context.additional_kwargs[key])

nvfp4._use_qwen38_qpn_batch_fused_w2:
def _use_qwen38_qpn_batch_fused_w2(
    layer: RoutedExperts,
    x: torch.Tensor,
    topk_ids: torch.Tensor,
) -> bool:
    """Admit the fixed-order parallel W2 reduction for direct batch QPN."""
    return bool(
        envs.VLLM_SM70_NVFP4_QWEN38_MOE_QPN_BATCH_FUSED_W2
        and sm70_ops.has_nvfp4_qpn_w2_reduce_dispatch()
        and _use_qwen38_qpn_batch_decode(layer, x, topk_ids)
    )

nvfp4._use_grouped_mtp5:
def _use_grouped_mtp5(layer, x: torch.Tensor, topk_ids: torch.Tensor) -> bool:
    """Keep MTP's admitted split4 arithmetic while sharing expert weights."""
    return bool(
        getattr(layer, "sm70_nvfp4_grouped_mtp5", False)
        and _use_qwen38_qpn_mtp5_decode(layer, x, topk_ids)
    )

nvfp4.apply:
def apply(self, layer: RoutedExperts, x: torch.Tensor, topk_weights: torch.Tensor, topk_ids: torch.Tensor, shared_experts: SharedExperts | None, shared_experts_input: torch.Tensor | None) -> torch.Tensor:
    del shared_experts, shared_experts_input
    if not x.is_cuda or x.dtype != torch.float16 or x.ndim != 2:
        raise TypeError('SM70 NVFP4 MoE requires CUDA FP16 activations [M, H].')
    if not is_exact_sm70_cuda(x, enabled=True):
        raise RuntimeError('SM70 NVFP4 MoE dispatch is restricted to CUDA SM70.')
    hidden = int(layer.sm70_nvfp4_hidden_size)
    top_k = int(layer.sm70_nvfp4_top_k)
    if x.shape[1] != hidden:
        raise ValueError(f'SM70 NVFP4 MoE activation hidden size mismatch: expected {hidden}, got {x.shape[1]}.')
    if tuple(topk_ids.shape) != (x.shape[0], top_k):
        raise ValueError(f'SM70 NVFP4 MoE top-k ID shape mismatch: expected {(x.shape[0], top_k)}, got {tuple(topk_ids.shape)}.')
    if tuple(topk_weights.shape) != tuple(topk_ids.shape):
        raise ValueError('SM70 NVFP4 MoE top-k weights and IDs must share shape.')
    if topk_weights.dtype != torch.float32:
        raise TypeError('SM70 NVFP4 MoE requires float32 top-k weights.')
    num_tokens = x.shape[0]
    if num_tokens == 0:
        return x.new_empty((0, hidden))
    indexed_w13 = _use_qwen38_indexed_prefill(layer, x, topk_ids)
    interleaved_w13 = bool(getattr(layer, 'sm70_nvfp4_qwen38_fused_swiglu_prefill', False))
    fused_indexed_w13 = indexed_w13 and interleaved_w13
    split_fused_indexed_w13 = fused_indexed_w13 and bool(getattr(layer, 'sm70_nvfp4_qwen38_fast_prefill', False))
    glm53_fused_permute_q8 = _use_glm53_fused_permute_q8(layer, x, topk_ids)
    glm53_qpn_w13_q8 = _use_glm53_qpn_w13_q8(layer, x, topk_ids, fused_permute=glm53_fused_permute_q8)
    buffers = self._get_buffers(layer, num_tokens, indexed_w13)
    output = buffers['output']
    slots = num_tokens * top_k
    grouped_mtp5 = _use_grouped_mtp5(layer, x, topk_ids)
    if grouped_mtp5 or _use_grouped_decode(layer, x, topk_ids):
        sm70_ops.nvfp4_grouped_w13_sm70_out(buffers['intermediate'], x, layer.w13_tm_weight, layer.w13_tm_scales, topk_ids.view(-1), layer._nvfp4_grouped_rows, layer._nvfp4_grouped_experts, layer._nvfp4_grouped_sizes, layer._nvfp4_grouped_total, 4 if grouped_mtp5 or num_tokens == 8 else 8, interleaved_w13)
        w2_op = sm70_ops.nvfp4_grouped_w2_batch_reduce_sm70_out if grouped_mtp5 else sm70_ops.nvfp4_grouped_w2_sm70_out
        w2_op(output, buffers['sorted_output'], buffers['intermediate'], layer.w2_tm_weight, layer.w2_tm_scales, topk_weights, layer._nvfp4_grouped_rows, layer._nvfp4_grouped_experts, layer._nvfp4_grouped_sizes, layer._nvfp4_grouped_total)
        logger.info_once('Experimental SM70 grouped native-NVFP4 decode selected (tokens=%d, W13/W2 share route groups, MTP split4/reduce=%s).', num_tokens, grouped_mtp5)
        return output
    direct_single_token = num_tokens == 1
    direct_qpn_m1 = _use_qwen38_qpn_m1_decode(layer, x, topk_ids)
    direct_qpn_batch = _use_qwen38_qpn_batch_decode(layer, x, topk_ids)
    direct_qpn_mtp5 = _use_qwen38_qpn_mtp5_decode(layer, x, topk_ids)
    raw_scale = bool(getattr(layer, 'sm70_nvfp4_qwen38_raw_scale', False))
    if os.getenv('VLLM_SM70_QWEN38_QPN_ROUTE_DEBUG') == '1' and num_tokens <= 16:
        logger.warning_once('SM70 Qwen3.8 QPN route debug: tokens=%d x_shape=%s x_stride=%s x_dtype=%s x_contiguous=%s ids_shape=%s ids_stride=%s ids_dtype=%s ids_contiguous=%s tp=%s experts=%s hidden=%s intermediate=%s top_k=%s m1=%s batch=%s mtp5=%s compiling=%s capturing=%s.', num_tokens, tuple(x.shape), tuple(x.stride()), x.dtype, x.is_contiguous(), tuple(topk_ids.shape), tuple(topk_ids.stride()), topk_ids.dtype, topk_ids.is_contiguous(), layer.moe_config.tp_size, layer.sm70_nvfp4_num_experts, layer.sm70_nvfp4_hidden_size, layer.sm70_nvfp4_intermediate_size, layer.sm70_nvfp4_top_k, direct_qpn_m1, direct_qpn_batch, direct_qpn_mtp5, torch.compiler.is_compiling(), torch.cuda.is_current_stream_capturing())
    if direct_qpn_m1 or direct_qpn_batch or direct_qpn_mtp5:
        if direct_qpn_m1:
            w13_split_k = _QWEN38_QPN_M1_W13_SPLIT_K
        elif direct_qpn_batch:
            split_table = _QWEN38_DYNAMIC_QPN_BATCH_W13_SPLIT_K if envs.VLLM_SM70_NVFP4_QWEN38_MOE_QPN_DYNAMIC_DECODE else _QWEN38_QPN_BATCH_W13_SPLIT_K
            w13_split_k = split_table[num_tokens]
        else:
            w13_split_k = _QWEN38_QPN_MTP5_W13_SPLIT_K
        logger.info_once('SM70 Qwen3.8 NVFP4 direct expert path enabled (TP4, E512/K10, tokens=%d, W13 split%d, W2 split1).', num_tokens, w13_split_k)
        route_ids = topk_ids.view(-1)
        direct_op = sm70_ops.nvfp4_moe_qpn_mtp5_sm70_out if direct_qpn_mtp5 else sm70_ops.nvfp4_moe_qpn_m1_sm70_out
        fused_batch_w13 = _use_qwen38_qpn_batch_fused_w13(layer, x, topk_ids)
        fused_w13_decode = bool(direct_qpn_m1 and (not raw_scale) and interleaved_w13 and getattr(layer, 'sm70_nvfp4_qwen38_fused_swiglu_decode', False))
        if fused_w13_decode:
            sm70_ops.nvfp4_qwen38_w13_fused_swiglu_out(buffers['intermediate'], x, layer.w13_tm_weight, layer.w13_tm_scales, route_ids)
        elif fused_batch_w13:
            logger.info_once('SM70 Qwen3.8 NVFP4 direct W13+SwiGLU fusion enabled (tokens=%d).', num_tokens)
            if raw_scale:
                sm70_ops.nvfp4_moe_qpn_raw_w13_swiglu_batch_sm70_out(buffers['intermediate'], x, layer.w13_tm_weight, layer.w13_raw_scale_codes, layer.w13_raw_global_scales, route_ids, interleaved_w13)
            else:
                sm70_ops.nvfp4_moe_qpn_w13_swiglu_batch_sm70_out(buffers['intermediate'], x, layer.w13_tm_weight, layer.w13_tm_scales, route_ids, interleaved_w13)
        else:
            if raw_scale:
                sm70_ops.nvfp4_moe_qpn_raw_scale_sm70_out(buffers['gate_up'], x, layer.w13_tm_weight, layer.w13_raw_scale_codes, layer.w13_raw_global_scales, route_ids, True, interleaved_w13, w13_split_k)
            else:
                direct_op(buffers['gate_up'], x, layer.w13_tm_weight, layer.w13_tm_scales, route_ids, True, w13_split_k)
            self._apply_swiglu(layer, buffers['intermediate'], buffers['gate_up'], interleaved=interleaved_w13)
        if direct_qpn_m1 and (not raw_scale) and getattr(layer, 'sm70_nvfp4_qwen38_w2_direct_reduce', False):
            sm70_ops.nvfp4_qwen38_w2_direct_reduce_out(output, buffers['intermediate'], layer.w2_tm_weight, layer.w2_tm_scales, route_ids, topk_weights)
            return output
        if _use_qwen38_qpn_batch_fused_w2(layer, x, topk_ids):
            logger.info_once('SM70 Qwen3.8 NVFP4 direct W2+weighted-reduce fusion enabled (tokens=%d).', num_tokens)
            if raw_scale:
                sm70_ops.nvfp4_moe_qpn_raw_w2_reduce_sm70_out(output, buffers['intermediate'], layer.w2_tm_weight, layer.w2_raw_scale_codes, layer.w2_raw_global_scales, route_ids, topk_weights)
            else:
                sm70_ops.nvfp4_moe_qpn_w2_reduce_sm70_out(output, buffers['intermediate'], layer.w2_tm_weight, layer.w2_tm_scales, route_ids, topk_weights)
            return output
        if raw_scale:
            sm70_ops.nvfp4_moe_qpn_raw_scale_sm70_out(buffers['sorted_output'], buffers['intermediate'], layer.w2_tm_weight, layer.w2_raw_scale_codes, layer.w2_raw_global_scales, route_ids, False, False, _QWEN38_QPN_M1_W2_SPLIT_K)
        else:
            direct_op(buffers['sorted_output'], buffers['intermediate'], layer.w2_tm_weight, layer.w2_tm_scales, route_ids, False, _QWEN38_QPN_M1_W2_SPLIT_K)
        if direct_qpn_m1:
            _single_token_weighted_reduce(buffers['sorted_output'], topk_weights, output)
        else:
            _mtp_weighted_reduce(buffers['sorted_output'], topk_weights, output)
        return output
    if direct_single_token:
        _prepare_single_token_slots(x, topk_ids, buffers['permuted_input'], buffers['active_expert_ids'])
        stage_offsets = buffers['compact_offsets']
        stage_expert_ids = buffers['active_expert_ids']
        stage_experts = top_k
    elif glm53_fused_permute_q8:
        sm70_ops.sm70_glm53_moe_permute_q8_out(x, topk_ids, buffers['permuted_input'], buffers['sorted_row_idx'], buffers['inv_permuted_idx'], buffers['compact_offsets'], buffers['active_expert_ids'])
        stage_offsets = buffers['compact_offsets']
        stage_expert_ids = buffers['active_expert_ids']
        stage_experts = slots
    else:
        output.zero_()
        topk_ids_i32 = buffers['topk_ids']
        topk_ids_i32.copy_(topk_ids, non_blocking=True)
        buffers['permuted_idx'].fill_(slots)
        if indexed_w13:
            torch.ops._moe_C.moe_permute_metadata_with_scratch(x, topk_ids_i32, buffers['token_expert_indices'], layer.expert_map, layer.global_num_experts, layer.local_num_experts, top_k, buffers['expert_offsets64'], buffers['inv_permuted_idx'], buffers['permuted_idx'], buffers['input_row_indices'], buffers['sort_workspace'], buffers['permuted_experts_id'], buffers['sorted_row_idx'], buffers['topk_ids_for_sort'])
        else:
            torch.ops._moe_C.moe_permute_with_scratch(x, topk_ids_i32, buffers['token_expert_indices'], layer.expert_map, layer.global_num_experts, layer.local_num_experts, top_k, buffers['permuted_input'], buffers['expert_offsets64'], buffers['inv_permuted_idx'], buffers['permuted_idx'], buffers['sort_workspace'], buffers['permuted_experts_id'], buffers['sorted_row_idx'], buffers['topk_ids_for_sort'])
        buffers['expert_offsets'].copy_(buffers['expert_offsets64'], non_blocking=True)
    if not direct_single_token and (not glm53_fused_permute_q8) and _use_compact_grouped(num_tokens, top_k):
        prepare_groups = _prepare_compact_expert_groups if _use_glm53_grouped_expert_rows(layer, num_tokens) else _prepare_compact_slot_groups
        prepare_groups(buffers['permuted_experts_id'], buffers['compact_offsets'], buffers['active_expert_ids'])
        stage_offsets = buffers['compact_offsets']
        stage_expert_ids = buffers['active_expert_ids']
        stage_experts = slots
    elif not direct_single_token and (not glm53_fused_permute_q8):
        stage_offsets = buffers['expert_offsets']
        stage_expert_ids = buffers['dense_expert_ids']
        stage_experts = int(layer.sm70_nvfp4_num_experts)
    if raw_scale:
        sm70_ops.nvfp4_expand_raw_scales_sm70_out(layer.w13_tm_scales, layer.w13_raw_scale_codes, layer.w13_raw_global_scales, interleaved_w13)
    if split_fused_indexed_w13:
        logger.info_once('SM70 Qwen3.8 NVFP4 indexed-A fused-SwiGLU split-W13 prefill route enabled (N256+N64).')
        for intermediate, ptrs_w, ptrs_s, n in ((buffers['intermediate'][:, :128], layer.w13_head_strided_ptrs_w, layer.w13_head_strided_ptrs_s, 256), (buffers['intermediate'][:, 128:], layer.w13_tail_strided_ptrs_w, layer.w13_tail_strided_ptrs_s, 64)):
            sm70_ops.nvfp4_moe_indexed_fused_swiglu_sm70_out(intermediate, x, buffers['input_row_indices'], stage_offsets, stage_expert_ids, ptrs_w, ptrs_s, stage_experts, layer.sm70_nvfp4_w13_k_dim, n, layer.sm70_nvfp4_group_size)
    elif fused_indexed_w13:
        logger.info_once('SM70 Qwen3.8 NVFP4 indexed-A fused-SwiGLU W13 prefill candidate enabled.')
        sm70_ops.nvfp4_moe_indexed_fused_swiglu_sm70_out(buffers['intermediate'], x, buffers['input_row_indices'], stage_offsets, stage_expert_ids, layer.w13_strided_ptrs_w, layer.w13_strided_ptrs_s, stage_experts, layer.sm70_nvfp4_w13_k_dim, layer.sm70_nvfp4_w13_n_dim, layer.sm70_nvfp4_group_size)
    elif indexed_w13:
        logger.info_once('SM70 Qwen3.8 NVFP4 indexed-A W13 prefill route enabled (TP4, E512/K10, materialized input rows skipped).')
        sm70_ops.nvfp4_moe_indexed_dense_stage_sm70_out(buffers['gate_up'], x, buffers['input_row_indices'], stage_offsets, stage_expert_ids, layer.w13_strided_ptrs_w, layer.w13_strided_ptrs_s, stage_experts, layer.sm70_nvfp4_w13_k_dim, layer.sm70_nvfp4_w13_n_dim, layer.sm70_nvfp4_group_size)
    elif glm53_qpn_w13_q8:
        logger.info_once('SM70 GLM-5.3 TP8 q8 exact W13 QPN path enabled (CTA-K32 split-3 accumulation tree).')
        sm70_ops.nvfp4_glm53_moe_q8_qpn_sm70_out(buffers['gate_up'], buffers['permuted_input'], layer.w13_tm_weight, layer.w13_tm_scales, topk_ids.view(-1), buffers['sorted_row_idx'], True)
    else:
        sm70_ops.nvfp4_moe_dense_stage_sm70_out(buffers['gate_up'], buffers['permuted_input'], stage_offsets, stage_expert_ids, layer.w13_strided_ptrs_w, layer.w13_strided_ptrs_s, stage_experts, layer.sm70_nvfp4_w13_k_dim, layer.sm70_nvfp4_w13_n_dim, layer.sm70_nvfp4_group_size)
    if not fused_indexed_w13:
        self._apply_swiglu(layer, buffers['intermediate'], buffers['gate_up'], interleaved=interleaved_w13)
    if raw_scale:
        sm70_ops.nvfp4_expand_raw_scales_sm70_out(layer.w2_tm_scales, layer.w2_raw_scale_codes, layer.w2_raw_global_scales, False)
    sm70_ops.nvfp4_moe_dense_stage_sm70_out(buffers['sorted_output'], buffers['intermediate'], stage_offsets, stage_expert_ids, layer.w2_strided_ptrs_w, layer.w2_strided_ptrs_s, stage_experts, layer.sm70_nvfp4_w2_k_dim, layer.sm70_nvfp4_w2_n_dim, layer.sm70_nvfp4_group_size)
    if direct_single_token:
        _single_token_weighted_reduce(buffers['sorted_output'], topk_weights, output)
    else:
        torch.ops._moe_C.moe_unpermute(buffers['sorted_output'], topk_weights, buffers['inv_permuted_idx'], None if glm53_fused_permute_q8 else buffers['expert_offsets64'], top_k, output)
    global _DFLASH_NVFP4_TRACE_ARMED
    if _DFLASH_NVFP4_TRACE_ARMED and num_tokens > 1:
        _DFLASH_NVFP4_TRACE_ARMED = False
        actual = output.clone()
        reference_rows = []
        for token_idx in range(num_tokens):
            reference_rows.append(self.apply(layer, x[token_idx:token_idx + 1], topk_weights[token_idx:token_idx + 1], topk_ids[token_idx:token_idx + 1], None, None).clone())
        reference = torch.cat(reference_rows, dim=0)
        delta = (actual - reference).float().reshape(num_tokens, -1)
        logger.warning('DFLASH_TARGET_NVFP4_SEQUENCE_DELTA tokens=%d max_by_token=%s mean_by_token=%s sqsum_by_token=%s routes=%s', num_tokens, delta.abs().amax(dim=1).cpu().tolist(), delta.abs().mean(dim=1).cpu().tolist(), (delta * delta).sum(dim=1).cpu().tolist(), topk_ids.detach().cpu().tolist())
        output.copy_(actual)
    return output

mxfp4._mxfp4_qpn_m1_extension_enabled:
def _mxfp4_qpn_m1_extension_enabled() -> bool:
    """Resolve the default-on route without breaking an older extension."""
    if not envs.VLLM_SM70_MXFP4_MOE_QPN_M1_DECODE:
        return False
    if _mxfp4_qpn_m1_op_available():
        return True
    if os.getenv(_MXFP4_QPN_M1_ENV) is not None:
        raise RuntimeError(
            "The explicitly enabled SM70 MXFP4 QPN M1 route requires the "
            f"source-built {_MXFP4_QPN_M1_OP} operator."
        )
    logger.warning_once(
        "The default SM70 MXFP4 QPN M1 route is unavailable in the loaded "
        "vllm._C; retaining the TurboMind dense-stage path."
    )
    return False

mxfp4._mxfp4_active_expert_b1_enabled:
def _mxfp4_active_expert_b1_enabled() -> bool:
    return bool(
        envs.VLLM_SM70_MXFP4_MOE_ACTIVE_EXPERT_B1
        and not envs.VLLM_SM70_MOE_SINGLE_TOKEN_FASTPATH
        and not envs.VLLM_SM70_MOE_SINGLE_TOKEN_PERMUTE_FASTPATH
    )

mxfp4._mxfp4_active_expert_max_tokens:
def _mxfp4_active_expert_max_tokens() -> int:
    if not _mxfp4_active_expert_b1_enabled():
        return 0
    return min(
        int(envs.VLLM_SM70_MXFP4_MOE_ACTIVE_EXPERT_MAX_TOKENS),
        _GRAPH_SAFE_MAX_TOKENS,
    )

mxfp4._mxfp4_grouped_verifier_for_tokens:
def _mxfp4_grouped_verifier_for_tokens(num_tokens: int) -> bool:
    return bool(
        (num_tokens == _GRAPH_SAFE_MAX_TOKENS and _mxfp4_grouped_m8_enabled())
        or (
            1 < num_tokens <= _GRAPH_SAFE_MAX_TOKENS
            and _mxfp4_grouped_verifier_enabled()
        )
    )

mxfp4._mxfp4_grouped_m8_expert_rows_enabled:
def _mxfp4_grouped_m8_expert_rows_enabled() -> bool:
    return bool(
        (_mxfp4_grouped_m8_enabled() or _mxfp4_grouped_verifier_enabled())
        and envs.VLLM_SM70_MXFP4_MOE_GROUPED_M8_EXPERT_ROWS
    )

mxfp4._select_mxfp4_stage_dispatch:
def _select_mxfp4_stage_dispatch(
    buffers: dict[str, torch.Tensor],
    *,
    num_tokens: int,
    num_experts: int,
    fully_replicated_experts: bool,
) -> tuple[torch.Tensor, torch.Tensor, int]:
    if 0 < num_tokens <= _mxfp4_active_expert_max_tokens() and fully_replicated_experts:
        # Keep the graph launch count fixed. The compactor represents unused
        # tail entries as zero-row experts, avoiding a host readback of the
        # dynamic unique-expert count.
        graph_expert_slots = num_tokens * _DEEPSEEK_V4_FLASH_TOP_K
        if _mxfp4_grouped_verifier_for_tokens(num_tokens):
            if _mxfp4_grouped_m8_expert_rows_enabled():
                return (
                    buffers["compact_expert_offsets"],
                    buffers["active_expert_ids"],
                    graph_expert_slots,
                )
            return (
                buffers["slot_expert_offsets"],
                buffers["permuted_experts_id"],
                graph_expert_slots,
            )
        return (
            buffers["compact_expert_offsets"],
            (
                buffers["permuted_experts_id"]
                if num_tokens == 1
                else buffers["active_expert_ids"]
            ),
            graph_expert_slots,
        )
    return buffers["expert_offsets"], buffers["dense_expert_ids"], num_experts
